module haybale_sort (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] s,\n    output reg [3:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [1:0] IDLE    = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] DONE_ST = 2'd2;\n    \n    reg [1:0] state;\n    reg [1:0] next_state;\n    \n    // Combinational logic\n    reg [4:0] inv;\n    reg has_2_inv;\n    reg [4:0] ceil_half;\n    reg [3:0] result_comb;\n    \n    integer i;\n    reg [2:0] zeros_suffix [0:8];\n    \n    always @(*) begin\n        // Compute suffix zeros\n        zeros_suffix[8] = 3'd0;\n        for (i = 7; i >= 0; i = i - 1) begin\n            zeros_suffix[i] = s[i] ? 3'd0 : (zeros_suffix[i+1] + 3'd1);\n        end\n        \n        // Compute inversion count\n        inv = 5'd0;\n        for (i = 0; i < 8; i = i + 1) begin\n            if (s[i]) inv = inv + zeros_suffix[i+1];\n        end\n        \n        // Check PCC/PPC triples\n        has_2_inv = 1'b0;\n        for (i = 0; i <= 5; i = i + 1) begin\n            if ((s[i] & ~s[i+1] & ~s[i+2]) || (s[i] & s[i+1] & ~s[i+2])) begin\n                has_2_inv = 1'b1;\n            end\n        end\n        \n        // Compute ceil(inv/2)\n        ceil_half = (inv + 5'd1) >> 1;\n        \n        // Determine result\n        if (inv == 5'd0) begin\n            result_comb = 4'd0;\n        end else if (has_2_inv) begin\n            result_comb = ceil_half[3:0];\n        end else if (inv[0]) begin\n            result_comb = ceil_half[3:0];\n        end else begin\n            result_comb = ceil_half[3:0] + 4'd1;\n        end\n    end\n    \n    // Sequential logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 4'd0;\n            done <= 1'b0;\n        end else begin\n            state <= next_state;\n            \n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        next_state <= COMPUTE;\n                    end else begin\n                        next_state <= IDLE;\n                    end\n                end\n                \n                COMPUTE: begin\n                    result <= result_comb;\n                    next_state <= DONE_ST;\n                end\n                \n                DONE_ST: begin\n                    done <= 1'b1;\n                    next_state <= IDLE;\n                end\n                \n                default: next_state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule